  'Latin American History',
  'A survey of Latin American history from pre-Columbian societies to the contemporary era. Students analyze conquest, colonialism, slavery, race, gender, labor, religion, and state formation with primary and secondary sources, compare national and regional experiences, and connect Latin America to Atlantic, Pacific, U.S., indigenous, African diaspora, and global histories.',
  $lathjson${"slug": "latin-american-history", "title": "Latin American History", "description": "A survey of Latin American history from pre-Columbian societies to the contemporary era. Students analyze conquest, colonialism, slavery, race, gender, labor, religion, and state formation with primary and secondary sources, compare national and regional experiences, and connect Latin America to Atlantic, Pacific, U.S., indigenous, African diaspora, and global histories.", "topics": [{"id": "7dd8f8af-53a7-4315-97d0-83c961f2d71d", "type": "topic", "title": "Historical Method, Geography, and the Idea of Latin America", "description": "Frame Latin America as a historically constructed region shaped by indigenous worlds, Iberian empires, Africa, migration, capitalism, and U.S./global power.", "children": [{"id": "2b6adfab-641e-47b9-aab9-9d034fff61d6", "type": "subtopic", "title": "Region, language, and naming", "children": [{"id": "15b55610-239a-4ee5-8f4e-6fba26cbcbb2", "type": "concept", "title": "Latin America, Ibero-America, the Caribbean, and Abya Yala"}, {"id": "017003f7-b934-4dc9-95f4-6fc46e7e47e7", "type": "concept", "title": "Spanish-, Portuguese-, French-, English-, and indigenous-language worlds"}, {"id": "0bc9749b-af12-4e26-aa96-43848fdd5e8d", "type": "concept", "title": "Mesoamerica, Andes, Amazonia, Southern Cone, Caribbean, and borderlands"}, {"id": "168bdaa2-1f12-4baa-bbb2-35d86ae88f9d", "type": "concept", "title": "Region as historical argument rather than fixed geography"}], "description": "Students begin by asking what Latin America means, who uses the term, and what histories the label includes or hides."}, {"id": "eeb5c9b8-d459-4bcb-b553-d37ef5c9dad8", "type": "subtopic", "title": "Sources and historical interpretation", "children": [{"id": "7c359657-ae5e-464f-b0d0-0d4e5dd9fb37", "type": "concept", "title": "Primary and secondary sources"}, {"id": "115cab09-1975-43b6-aa62-ea37ecc1fb3e", "type": "concept", "title": "Translation and colonial mediation"}, {"id": "0ec433d7-a8f9-4a3b-8ea0-e477f2b5ac67", "type": "concept", "title": "Archives, silence, and power"}, {"id": "c7c927be-ce13-476f-9563-99505b4df1a2", "type": "concept", "title": "Chronology, causation, and comparison"}], "description": "This subtopic builds the habits needed to read chronicles, court records, maps, oral histories, photographs, testimony, and scholarship critically."}, {"id": "f3f6511c-5dd9-4564-ba10-8a2a0ae2cc87", "type": "subtopic", "title": "Scale and connected histories", "children": [{"id": "7debeec4-d5ab-4c87-8fe7-7fc9e747bb5f", "type": "concept", "title": "Village, city, region, nation, empire, and world-system scales"}, {"id": "cdbc04ca-72f5-4bde-8048-1e2bfe46c964", "type": "concept", "title": "Atlantic and Pacific worlds"}, {"id": "730f5920-fcce-4394-9bd5-1b204d28c862", "type": "concept", "title": "U.S.-Latin American relations"}, {"id": "7ac69a50-58a9-4fbc-b508-03844de94b42", "type": "concept", "title": "Migration, diaspora, and transnational history"}], "description": "Latin American history becomes more intelligible when local communities, imperial systems, Atlantic/Pacific circuits, and global capitalism are studied together."}]}, {"id": "79c07580-4429-4336-961b-4ffb79222690", "type": "topic", "title": "Indigenous Americas before 1492", "description": "Study the diversity, scale, political sophistication, ecological knowledge, and cultural achievements of pre-Columbian societies.", "children": [{"id": "2f0fd1f0-495c-4832-8211-46789d474125", "type": "subtopic", "title": "Mesoamerican worlds", "children": [{"id": "4950a0e0-dd60-42e9-88e9-cf0b812b978f", "type": "concept", "title": "Olmec, Maya, Mexica/Aztec, and other societies"}, {"id": "dd2a8775-f592-43f4-a6f6-94425419a5d4", "type": "concept", "title": "Cities, tribute, calendars, and writing"}, {"id": "08af53b2-dd7b-4fa8-9c2f-c9092ee8d958", "type": "concept", "title": "Maize agriculture and chinampas"}, {"id": "7f087d77-380e-4648-8e75-d021c6d62ec0", "type": "concept", "title": "Religion, warfare, and political legitimacy"}], "description": "Students examine indigenous statecraft, urbanism, religion, agriculture, and writing before European arrival."}, {"id": "af3bbb3a-37bb-4c86-8939-59c530cb6c62", "type": "subtopic", "title": "Andean worlds", "children": [{"id": "55fcef0e-42df-4110-afa8-7c6780b04b10", "type": "concept", "title": "Chavin, Moche, Tiwanaku, Wari, and Inca"}, {"id": "dd868706-d318-407a-b105-bda699a1337c", "type": "concept", "title": "Ayllu, mit'a, and vertical archipelagos"}, {"id": "8521d195-0184-4f6d-b2d8-3870e7f5ec7f", "type": "concept", "title": "Quipu, roads, and imperial administration"}, {"id": "3463f65a-061c-46ed-ae58-26616f70f942", "type": "concept", "title": "Highland/coastal ecological systems"}], "description": "The Andes show another major path to complex society, empire, ecological management, and record keeping."}, {"id": "4411c513-df37-4393-ae2d-d53987dde7a3", "type": "subtopic", "title": "Caribbean, Amazonian, and diverse indigenous societies", "children": [{"id": "4c0f4530-f5f7-4ebe-8418-7077cdb3b0ea", "type": "concept", "title": "Taino and Carib societies"}, {"id": "57099eaf-f273-46dc-a9ec-b80a723022f3", "type": "concept", "title": "Amazonian settlement and earthworks"}, {"id": "4d3a813f-e2b4-40c7-a015-2e398c00c166", "type": "concept", "title": "Nomadic, semi-sedentary, and agricultural communities"}, {"id": "86f1de5d-da1e-4114-bdbb-0ac2e75070b4", "type": "concept", "title": "Indigenous diplomacy, trade, and environmental knowledge"}], "description": "The course avoids reducing pre-Columbian history to only empires by studying varied political and ecological forms."}]}, {"id": "46f76170-3717-4315-bcc1-11638d46eedf", "type": "topic", "title": "Conquest, Encounter, Disease, and Colonial Violence", "description": "Analyze conquest as a contested process involving indigenous allies, military force, epidemic disease, translation, law, and memory.", "children": [{"id": "5a0481f2-a415-4d53-bdbc-b72ab109d1e4", "type": "subtopic", "title": "Conquest as contested process", "children": [{"id": "6e352e0b-8f98-44b8-b344-7e56b2115535", "type": "concept", "title": "Cortes, Malintzin, and indigenous allies"}, {"id": "19773756-07b7-407d-bdc7-8ae31bd0b9cd", "type": "concept", "title": "Pizarro and Andean civil war"}, {"id": "029ad4a7-4a18-45a4-8505-9472cd92b954", "type": "concept", "title": "Spanish, Portuguese, and Caribbean encounters"}, {"id": "03f5bfae-67aa-4a00-a233-1588d9a7cf1c", "type": "concept", "title": "Military technology, horses, and local politics"}], "description": "Conquest was not inevitable; it depended on alliances, rivalries, intelligence, technology, disease, and indigenous strategy."}, {"id": "556c6359-fe00-4c17-8435-e3ef40e31db0", "type": "subtopic", "title": "Disease and demographic catastrophe", "children": [{"id": "cb84c5db-44e5-4467-a3e1-d26fad7c7a51", "type": "concept", "title": "Smallpox, measles, influenza, and mortality"}, {"id": "cc84606a-7f06-4ae3-b537-f4b15374d521", "type": "concept", "title": "Demographic debate and evidence"}, {"id": "b4644772-2e47-47fe-ab27-81d91ed1062b", "type": "concept", "title": "Community disruption and resettlement"}, {"id": "f51029cd-0cff-415c-8a53-2da100cdbb62", "type": "concept", "title": "Disease, ecology, and colonial rule"}], "description": "Students learn how epidemics transformed power, labor, land, spirituality, and community survival."}, {"id": "a25aeeec-4f29-4cea-9bf4-83258c4394f3", "type": "subtopic", "title": "Memory, law, and conquest narratives", "children": [{"id": "86f6dcd7-5d93-4974-b830-b0b12186a426", "type": "concept", "title": "Chronicles and relaciones"}, {"id": "ac9c54f6-ed9a-45a9-8618-693d4d61a16c", "type": "concept", "title": "Las Casas and debates over conquest"}, {"id": "f51076b7-8997-4f9f-aee5-d8493b5ac6b2", "type": "concept", "title": "Indigenous pictorial and alphabetic accounts"}, {"id": "87f4b006-8e58-4896-af5a-be25371d4e06", "type": "concept", "title": "Conquest memory in modern nationalism"}], "description": "Accounts of conquest were arguments about legitimacy, rights, violence, and moral responsibility."}]}, {"id": "60639bdb-b65e-491a-a541-2b0382771558", "type": "topic", "title": "Iberian Colonial Rule: Crown, Church, Cities, and Law", "description": "Understand how Spanish and Portuguese empires governed territory, souls, labor, land, and local communities.", "children": [{"id": "d109e233-6693-43d0-9df1-072b787dbb28", "type": "subtopic", "title": "Colonial institutions", "children": [{"id": "4c79af57-2c72-4612-842f-dcefe7a20a2d", "type": "concept", "title": "Viceroyalties, audiencias, cabildos, and governors"}, {"id": "dee3914e-07bd-47d2-8ea5-2087d24c00d7", "type": "concept", "title": "Portuguese captaincies and Brazil's colonial administration"}, {"id": "7a028ecd-28ff-4252-af0f-454ada1c7e9f", "type": "concept", "title": "Bureaucracy, patronage, and corruption"}, {"id": "e9d0ac24-d86d-4c1f-bc39-ff47870987be", "type": "concept", "title": "Cities as colonial power centers"}], "description": "Students identify the administrative machinery of empire and how distant monarchies governed local worlds."}, {"id": "57d08b4b-a57b-4abf-8e5b-63527488f235", "type": "subtopic", "title": "Church, conversion, and religious life", "children": [{"id": "b0b93bc2-3f9a-4edc-99d6-78183930fa35", "type": "concept", "title": "Missionary orders and evangelization"}, {"id": "c9210a2b-13ce-4d64-9c8d-ea0472aa7193", "type": "concept", "title": "Syncretism and indigenous Christianity"}, {"id": "42837c7d-7b37-4cbf-942f-0f1e7680ac90", "type": "concept", "title": "Inquisition and moral regulation"}, {"id": "28ae834a-a05e-4d16-b4af-543afa17e4aa", "type": "concept", "title": "Confraternities, festivals, and popular religion"}], "description": "Religion was central to colonization, education, social discipline, cultural exchange, and resistance."}, {"id": "504e1867-98b8-43f9-93bb-3d8c88efaad5", "type": "subtopic", "title": "Law and indigenous communities", "children": [{"id": "fd227b0b-5186-4725-b2ca-54f108691d74", "type": "concept", "title": "Republic of Indians and Republic of Spaniards"}, {"id": "0b1d4e08-da4b-4791-b4ff-619c9f7faa5e", "type": "concept", "title": "Tribute and resguardos"}, {"id": "63ed1268-95b9-48fa-bf90-bb3eaefdcd53", "type": "concept", "title": "Land titles and legal petitions"}, {"id": "239de905-60e7-493e-9d90-05aae32aa41d", "type": "concept", "title": "Customary authority and native cabildos"}], "description": "Colonial rule depended on legal categories that both constrained and enabled indigenous survival."}]}, {"id": "822d47b4-6853-4d50-8543-b2e648bec665", "type": "topic", "title": "Race, Caste, Gender, Family, and Everyday Colonial Society", "description": "Examine how colonial hierarchy was made through race, gender, sexuality, honor, household life, religion, and legal categories.", "children": [{"id": "7303340a-b162-4f33-aa25-e1f4cb264967", "type": "subtopic", "title": "Caste and racial formation", "children": [{"id": "f8c45cc6-c2d4-46ad-960e-75a4be79af11", "type": "concept", "title": "Spaniards, Portuguese, indigenous peoples, Africans, mestizos, mulattos, and castas"}, {"id": "c88ce3c9-0083-4e55-b27b-c359c4e331db", "type": "concept", "title": "Limpieza de sangre and honor"}, {"id": "5885dd89-ccc7-4cbb-8b50-dbd3efd2f51a", "type": "concept", "title": "Casta paintings and visual classification"}, {"id": "0b01c179-5faf-4708-8063-37b393fe5125", "type": "concept", "title": "Mobility, ambiguity, and passing"}], "description": "Race in colonial Latin America was made through law, labor, ancestry, reputation, appearance, and local negotiation."}, {"id": "44deef19-55c0-4663-86ff-c053763deef8", "type": "subtopic", "title": "Gender, sexuality, and household power", "children": [{"id": "bc14267a-3d9b-4967-a035-c319b366f53a", "type": "concept", "title": "Patriarchy and legal dependence"}, {"id": "42cdee81-22d3-41ab-9aa7-736244f8f679", "type": "concept", "title": "Marriage, dowry, and legitimacy"}, {"id": "72b88dec-88c5-40d9-9b29-eab17feb968b", "type": "concept", "title": "Sexual regulation and honor"}, {"id": "9ad9237e-65fb-4ee3-bea3-03d011d3591d", "type": "concept", "title": "Women in markets, households, convents, and courts"}], "description": "Colonial power operated through marriage, inheritance, reproduction, sexuality, domestic labor, and family status."}, {"id": "8af68f34-8662-4263-8e69-e961af2745d1", "type": "subtopic", "title": "Everyday life and popular culture", "children": [{"id": "c9ca8ad4-4770-47dd-9414-03e1fddc2c45", "type": "concept", "title": "Urban neighborhoods and rural villages"}, {"id": "482260b4-4896-4103-8836-3be3b2df038c", "type": "concept", "title": "Foodways, dress, music, and devotion"}, {"id": "3693ba79-4ca8-4896-8904-19777d3d911d", "type": "concept", "title": "Crime, courts, and social conflict"}, {"id": "7501fe9b-0b79-412d-882f-0054a75db489", "type": "concept", "title": "Popular healing, magic, and belief"}], "description": "Students examine how ordinary people shaped colonial society through work, faith, festivals, markets, conflict, and community life."}]}, {"id": "4bcf70d9-1bdc-460b-9a41-834f61cf466c", "type": "topic", "title": "Labor, Slavery, Mining, Plantations, and Atlantic/Pacific Economies", "description": "Connect Latin America to global capitalism through coerced labor, silver, sugar, slavery, trade, and environmental transformation.", "children": [{"id": "836331d8-3ba0-46a9-a810-afa4f30d76c0", "type": "subtopic", "title": "Coerced labor regimes", "children": [{"id": "5ec4224d-a9e9-433e-b930-c2b1ed805a21", "type": "concept", "title": "Encomienda, repartimiento, and mit'a"}, {"id": "0e0764d6-09eb-45fd-8b91-2fdccd25513b", "type": "concept", "title": "African slavery"}, {"id": "0d6af7a4-0588-4372-afc2-d51762c540b5", "type": "concept", "title": "Debt peonage and wage labor"}, {"id": "268d0a87-46d3-4c83-a6e2-5b37e3793926", "type": "concept", "title": "Domestic, artisan, and informal labor"}], "description": "Colonial economies were built on overlapping systems of forced, semi-free, and wage labor."}, {"id": "948ed347-ee21-4253-98c3-060734f4347a", "type": "subtopic", "title": "Silver, sugar, and global trade", "children": [{"id": "090bb54a-dd80-4869-9760-c79f21d55df8", "type": "concept", "title": "Potosi, Zacatecas, and mercury"}, {"id": "a04bc2dd-7475-4d67-b249-4a304c4bffc9", "type": "concept", "title": "Sugar plantations in Brazil and the Caribbean"}, {"id": "6d72ddc7-16a7-49a1-b848-74499b966d87", "type": "concept", "title": "Manila galleons and Pacific trade"}, {"id": "d9b1097b-b3e2-4eac-bce5-6f6693f9112f", "type": "concept", "title": "Contraband, piracy, and port cities"}], "description": "Latin America powered early modern global exchange through mines, plantations, ports, and transoceanic routes."}, {"id": "bac69496-8155-4672-9e36-5988647a3d4b", "type": "subtopic", "title": "Environment and extraction", "children": [{"id": "22ffa319-2a77-41f8-9f1d-27bab4e82516", "type": "concept", "title": "Deforestation and mining pollution"}, {"id": "012efa27-7243-4ee3-a4ca-42a44527cbc9", "type": "concept", "title": "Plantation monocultures"}, {"id": "b21bf206-9c8c-4b47-a03c-45ff4741cf30", "type": "concept", "title": "Livestock and land use change"}, {"id": "1cb208c3-03a4-46ef-af82-742a218f1947", "type": "concept", "title": "Indigenous ecological knowledge and survival"}], "description": "Extraction changed landscapes, bodies, animals, crops, and disease environments."}]}, {"id": "44de7e0e-cf94-4d32-b452-2b5f23b64c4a", "type": "topic", "title": "Reform, Enlightenment, Rebellion, and Late Colonial Crisis", "description": "Trace Bourbon and Pombaline reforms, new political ideas, popular revolts, and the weakening of colonial legitimacy.", "children": [{"id": "918ee89f-57f6-43c0-9dcf-094c521b11e3", "type": "subtopic", "title": "Bourbon and Pombaline reforms", "children": [{"id": "71e4150b-e25a-4c37-b514-fc6d7459fe76", "type": "concept", "title": "Taxation and administrative centralization"}, {"id": "6997ada1-b83c-4673-b945-c4c5dc65620f", "type": "concept", "title": "Militias and imperial defense"}, {"id": "f2594547-e4e8-444e-b218-c4c0d3517d01", "type": "concept", "title": "Expulsion of the Jesuits"}, {"id": "dd644593-b7ed-436e-8f5b-17d0235c8376", "type": "concept", "title": "Free trade reforms and monopoly changes"}], "description": "Late colonial reforms attempted to make empire more profitable, centralized, and militarized, but also intensified social conflict."}, {"id": "30a1ecb0-898e-47f7-9646-ec67b33edb2e", "type": "subtopic", "title": "Enlightenment and Atlantic politics", "children": [{"id": "0f9e6986-6582-4478-a375-27e8bb0a1e35", "type": "concept", "title": "Creole patriotism"}, {"id": "b37f497c-5d58-4faa-84d5-c87edea1d56d", "type": "concept", "title": "Scientific expeditions"}, {"id": "cb34aadb-c772-4e0c-b67c-d5a4a340dbd8", "type": "concept", "title": "Print culture and censorship"}, {"id": "8055c826-50bb-42c5-bb49-c368ce8df62e", "type": "concept", "title": "Natural rights and political economy"}], "description": "New ideas about rights, sovereignty, science, economy, and reform circulated unevenly through colonial societies."}, {"id": "bbe81c4b-6046-4d84-8d31-1ddd0c8ca2cf", "type": "subtopic", "title": "Popular rebellion and crisis", "children": [{"id": "da303ff9-fd65-4567-8ac4-b6d897f01cad", "type": "concept", "title": "Tupac Amaru II and Andean rebellion"}, {"id": "34a46f1f-863f-4320-84c5-cea4d828d444", "type": "concept", "title": "Comunero revolts"}, {"id": "29433f73-936c-4a7a-bb3c-23e5765ae2d3", "type": "concept", "title": "Slave resistance and marronage"}, {"id": "e9512612-7d2b-4a97-bf41-6f258e92d174", "type": "concept", "title": "Haitian Revolution's regional impact"}], "description": "Rebellions reveal the limits of colonial authority and the diversity of indigenous, enslaved, creole, and popular politics."}]}, {"id": "915187e1-830c-44c6-8165-43bb764d0f64", "type": "topic", "title": "Independence Revolutions and Postcolonial State Formation", "description": "Compare independence movements and the difficult creation of republics, monarchies, constitutions, citizenship, and national territories.", "children": [{"id": "dce48a2e-fe4d-4660-883f-4dfc5a407ea2", "type": "subtopic", "title": "Causes and paths to independence", "children": [{"id": "890c84a3-56d8-41c9-bf6c-4b52e5b56340", "type": "concept", "title": "Napoleonic invasion of Iberia"}, {"id": "7cffe082-310c-44f1-96d8-19e7593c1255", "type": "concept", "title": "Juntas and sovereignty debates"}, {"id": "8c6a8b3a-4c1b-4053-80b8-11106d41051a", "type": "concept", "title": "Mexico, Gran Colombia, Rio de la Plata, Chile, Peru, and Brazil"}, {"id": "cd0b7932-9207-4a38-a470-30428a1be35a", "type": "concept", "title": "Haiti and the Caribbean"}], "description": "Independence emerged from imperial crisis, local grievances, Atlantic revolutions, social conflict, and military mobilization."}, {"id": "10eb7358-fe83-4134-9573-988aef0af1ea", "type": "subtopic", "title": "Leaders, armies, and popular participation", "children": [{"id": "725c51a1-fa06-413b-be09-d04cf9a54440", "type": "concept", "title": "Bolivar, San Martin, Hidalgo, Morelos, O'Higgins, and Pedro I"}, {"id": "af4bf636-b871-43f5-8c5b-c5fbb4cd2656", "type": "concept", "title": "Royalists and patriots"}, {"id": "2fae862a-df76-40e0-9f09-83ce5850cf24", "type": "concept", "title": "Guerrilla war and local mobilization"}, {"id": "cef9837f-b8d5-4fab-b71d-43263ab339d2", "type": "concept", "title": "Race, slavery, and promises of citizenship"}], "description": "Students compare elite projects with the actions of indigenous communities, enslaved people, free people of color, soldiers, and local militias."}, {"id": "2c2d3f2f-eb55-4e34-9e9d-1745ba913266", "type": "subtopic", "title": "Postcolonial state-building", "children": [{"id": "fe867249-6971-403b-a866-60331fb269d0", "type": "concept", "title": "Constitutions and republicanism"}, {"id": "f5f70343-f6cb-4b59-921b-8d3c867702eb", "type": "concept", "title": "Federalism versus centralism"}, {"id": "4581c74e-85a9-4c4c-85e5-f6fad0152623", "type": "concept", "title": "Military politics and caudillos"}, {"id": "8af91856-7d6f-4db8-b7bc-a0b5273c71ef", "type": "concept", "title": "Borders, debt, and diplomatic recognition"}], "description": "Independence did not automatically produce stable nations; it opened conflicts over authority, territory, citizenship, debt, and law."}]}, {"id": "0aa51b8d-2594-4330-ac47-71a0a140c5e4", "type": "topic", "title": "Nineteenth-Century Nation-Building, Liberalism, Caudillismo, and Citizenship", "description": "Study the conflicts over federalism, centralism, church power, race, land, indigenous rights, and political authority after independence.", "children": [{"id": "6afaeb6c-7ed5-458b-b779-d08a7ea66e6a", "type": "subtopic", "title": "Liberalism and conservative reaction", "children": [{"id": "0d37aa03-3612-4af7-af17-5a819419a1a7", "type": "concept", "title": "Church-state conflict"}, {"id": "b329d110-a7fc-4f22-84b4-54b114088593", "type": "concept", "title": "Civil codes and legal reform"}, {"id": "86b8739c-8069-4af5-bc9c-65737d1fe623", "type": "concept", "title": "Education and secularization"}, {"id": "4ea60e4c-6088-4ae6-af18-813b7df56ee6", "type": "concept", "title": "Conservative order and liberal reform"}], "description": "This subtopic explains the major political languages that shaped conflict over church, state, property, education, and citizenship."}, {"id": "49fa1a17-480c-4d44-9f71-3320c698cfa6", "type": "subtopic", "title": "Caudillismo, federalism, and regional power", "children": [{"id": "830bc2b9-8387-48a1-b840-dd33bdbefc48", "type": "concept", "title": "Caudillos and patron-client politics"}, {"id": "e02d7035-78e1-48b2-99d2-87cce3980b3f", "type": "concept", "title": "Federalist and centralist conflicts"}, {"id": "3fd2e7c7-1970-43c0-abcf-c4ef523396d0", "type": "concept", "title": "Civil wars and regionalism"}, {"id": "b7c15e42-c8c4-4e84-a2d0-ebe94848da60", "type": "concept", "title": "Military recruitment and taxation"}], "description": "Political instability becomes more understandable when students see how local power, war, patronage, and weak institutions interacted."}, {"id": "da65c94a-e02d-4731-bc93-546a3774af30", "type": "subtopic", "title": "Citizenship, race, and indigenous communities", "children": [{"id": "f75cfb3d-5c65-464d-8096-be3c1de87813", "type": "concept", "title": "Abolition and free womb laws"}, {"id": "84cf2b51-588c-4d21-b271-94ba9e529b03", "type": "concept", "title": "Indigenous land privatization"}, {"id": "10eabbcf-8e1c-49de-bd20-e429207b5344", "type": "concept", "title": "Literacy, property, and voting restrictions"}, {"id": "06399eba-af8b-4b69-b521-7aabb36c8e73", "type": "concept", "title": "National myths of mestizaje and whitening"}], "description": "Nation-building often promised equality while dispossessing or excluding indigenous, Afro-descendant, rural, and poor populations."}]}, {"id": "9c6e67ab-fa00-4a6f-88fc-bf5084ee76ed", "type": "topic", "title": "Export Economies, Land, Modernization, and Indigenous Dispossession", "description": "Analyze how railroads, coffee, sugar, nitrates, rubber, cattle, and land concentration remade societies and landscapes.", "children": [{"id": "e66e5972-02a3-496f-aabb-fa5cf398131a", "type": "subtopic", "title": "Export-led growth", "children": [{"id": "8f5ec451-e832-4c44-86ab-00b687e6553b", "type": "concept", "title": "Coffee, sugar, guano, nitrates, rubber, cattle, bananas, and copper"}, {"id": "c52246e7-d6f8-49b9-93c8-8b59cce27ced", "type": "concept", "title": "Railroads and ports"}, {"id": "2940db59-4808-4348-bb6f-cf4f7caf95e6", "type": "concept", "title": "British and U.S. investment"}, {"id": "423e6eed-9816-4dc4-bbbb-42680bf9f879", "type": "concept", "title": "Boom-and-bust cycles"}], "description": "Students study how global demand transformed national economies and deepened dependence on land, credit, railroads, and foreign capital."}, {"id": "84bbd330-7b31-465e-a683-65832cbab0e6", "type": "subtopic", "title": "Land, labor, and rural conflict", "children": [{"id": "43458ddd-acdc-40ec-a41f-3e35f685a369", "type": "concept", "title": "Haciendas and latifundia"}, {"id": "8cf22384-863f-4082-aac7-f32af9440475", "type": "concept", "title": "Debt peonage and labor drafts"}, {"id": "7831ede7-06a5-4a64-9f38-94d761657b54", "type": "concept", "title": "Liberal land laws"}, {"id": "7787abcc-a642-4fd9-ab7a-42acc14de898", "type": "concept", "title": "Rural rebellion and community defense"}], "description": "Modernization often concentrated land and coerced labor while provoking peasant and indigenous resistance."}, {"id": "ce614cdc-7d06-42d4-96b5-a16a71f560bc", "type": "subtopic", "title": "Modernity, cities, and inequality", "children": [{"id": "9549111e-b33b-42ad-8066-2abe972817f1", "type": "concept", "title": "Positivism and order/progress ideologies"}, {"id": "c4533441-b2b8-45f0-ac48-546e9b0fca96", "type": "concept", "title": "Urban planning and public health"}, {"id": "71c7ae49-87df-420e-b174-50cb3f7a255b", "type": "concept", "title": "Immigration and whitening projects"}, {"id": "e9d2a30a-5642-4d92-b2a8-e02572ed1df6", "type": "concept", "title": "Police, prisons, and social control"}], "description": "Urban elites promoted progress, science, and order while social inequality and racial exclusion persisted."}]}, {"id": "efda739c-9df0-415f-87a0-b7135e7da03b", "type": "topic", "title": "Revolution, Reform, and Social Movements", "description": "Examine major revolutionary and reform traditions, including Mexico, Cuba, labor organizing, peasant mobilization, student movements, and liberation theology.", "children": [{"id": "07d70725-1964-4c86-8b84-495ae1057f72", "type": "subtopic", "title": "Mexican Revolution", "children": [{"id": "ae5cdb22-5f90-4ce1-a9fa-5098e4f24e12", "type": "concept", "title": "Porfiriato and inequality"}, {"id": "feefde50-a0f7-4457-9cdf-c8e6e9e8865d", "type": "concept", "title": "Madero, Zapata, Villa, Carranza, and Cardenas"}, {"id": "e59fe5dc-2525-4478-9552-df7ea22a8c30", "type": "concept", "title": "Constitution of 1917"}, {"id": "a9a6116f-29ff-4d02-bbc5-8f12b76cba53", "type": "concept", "title": "Land reform, education, and cultural nationalism"}], "description": "The Mexican Revolution offers a major case for agrarian reform, popular mobilization, nationalism, constitutionalism, and state-building."}, {"id": "7ad88eba-4d0f-4a9f-b1b3-04c7a636886c", "type": "subtopic", "title": "Cuban Revolution and revolutionary imaginaries", "children": [{"id": "a8c8e976-fb6d-4d11-a63d-3ac8c3d544ab", "type": "concept", "title": "1959 revolution"}, {"id": "d1b21c07-2340-41e3-a7b7-18ffbb4a9742", "type": "concept", "title": "Fidel Castro, Che Guevara, and revolutionary state-building"}, {"id": "17dc6bde-3f7a-4df8-a912-891c2a24f77c", "type": "concept", "title": "Bay of Pigs and missile crisis"}, {"id": "65594009-dce7-43ee-b1c8-6df105346663", "type": "concept", "title": "Health, education, dissent, and exile"}], "description": "Cuba shaped regional debates about imperialism, socialism, nationalism, armed struggle, and social justice."}, {"id": "2b37355c-fd4c-47c4-9ca3-529dd51c8330", "type": "subtopic", "title": "Labor, students, peasants, and liberation theology", "children": [{"id": "0f6e7e5c-5d48-4cb0-b8ff-2ce235dbb9c2", "type": "concept", "title": "Unions and strikes"}, {"id": "3a69bf0c-4fd9-41d7-b6f0-775992b49801", "type": "concept", "title": "Student movements and 1968"}, {"id": "325fa2cd-f659-4ec2-9fa7-d29f35834661", "type": "concept", "title": "Peasant leagues and land occupations"}, {"id": "fd224713-c619-452c-8ea9-c3e7118f6ef5", "type": "concept", "title": "Base communities and liberation theology"}], "description": "Social movements show how ordinary people made history through organization, protest, cultural politics, and religious activism."}]}, {"id": "7aa16931-6089-47c1-9c32-1f4952515006", "type": "topic", "title": "Populism, Developmentalism, Urbanization, and Migration", "description": "Explore twentieth-century mass politics, import-substitution industrialization, labor rights, urban growth, migration, and cultural change.", "children": [{"id": "32cb6dc6-c753-4c8d-be50-3e5a2de8a918", "type": "subtopic", "title": "Populism and mass politics", "children": [{"id": "22a00de4-03ce-44ea-8c63-9b6851ed690b", "type": "concept", "title": "Peronism"}, {"id": "b9c35501-adae-4c46-bf6d-bdace3d4b07a", "type": "concept", "title": "Vargas and Estado Novo"}, {"id": "c65d99fd-32ef-4967-978f-36d2eccf7d5a", "type": "concept", "title": "Cardenismo"}, {"id": "49baebbe-978f-4a65-836e-750a57e824ba", "type": "concept", "title": "Mass parties, unions, and corporatism"}], "description": "Populism helps students understand charismatic leadership, labor incorporation, nationalism, welfare promises, and political polarization."}, {"id": "f7f48868-37cf-4281-a1f4-578f6fde2699", "type": "subtopic", "title": "Developmentalism and urban change", "children": [{"id": "fdb0b441-d728-4f61-bc56-eca01ae01122", "type": "concept", "title": "Import-substitution industrialization"}, {"id": "8f7f61bb-7e32-4530-9bf0-c5ecb3c93b9c", "type": "concept", "title": "State planning and public enterprises"}, {"id": "09dab1bb-6b1c-4361-bfbc-93dc296c90ef", "type": "concept", "title": "Informal settlements and urban services"}, {"id": "e5234aba-0c47-4999-8e8e-66205f580e1e", "type": "concept", "title": "Culture industries, radio, film, and television"}], "description": "Mid-twentieth-century states pursued industrialization and modernization while cities grew rapidly and unevenly."}, {"id": "75c4472a-684f-464e-8e2b-b1a6bd47e034", "type": "subtopic", "title": "Migration and transnational families", "children": [{"id": "1c52b328-c70c-4a70-9f46-bb5fccd5cfdd", "type": "concept", "title": "Rural-to-urban migration"}, {"id": "ee4ba444-1aeb-47ef-87b6-6305eb47fd2d", "type": "concept", "title": "Internal displacement"}, {"id": "4c38e446-9dec-42d6-bea9-fc62dbc3f711", "type": "concept", "title": "Guest work and border labor"}, {"id": "dc614e51-3150-42ec-be43-5bd303059bff", "type": "concept", "title": "Diaspora, remittances, and family separation"}], "description": "Migration links rural change, urbanization, labor markets, identity, remittances, and U.S.-Latin American relations."}]}, {"id": "6ef58fb0-c7eb-4416-9aad-0a0936685016", "type": "topic", "title": "Cold War Latin America: Intervention, Dictatorship, Revolution, and Human Rights", "description": "Study the Cold War through U.S. policy, revolutionary movements, military regimes, state terror, civil war, and human-rights struggles.", "children": [{"id": "2c898113-9071-4dc8-bc69-6b2ac2f94fb6", "type": "subtopic", "title": "U.S. policy and regional Cold War", "children": [{"id": "3b12c618-a32e-4611-80e3-97041566c325", "type": "concept", "title": "Guatemala 1954"}, {"id": "c6ca11a6-512b-4837-816a-186609184f2e", "type": "concept", "title": "Alliance for Progress"}, {"id": "0104dcf6-d5fb-405f-88b3-796539d8ee57", "type": "concept", "title": "School of the Americas"}, {"id": "8fc4dc75-b77c-4600-8268-861255c867ba", "type": "concept", "title": "CIA, coups, and counterinsurgency"}], "description": "Students connect Latin American politics to anticommunism, development aid, covert action, military training, and hemispheric security."}, {"id": "6a2a86a5-3d1d-4397-af76-5045cced9168", "type": "subtopic", "title": "Dictatorship, state terror, and civil war", "children": [{"id": "71ed76ca-4955-4195-9ff1-188b1c5032df", "type": "concept", "title": "Brazil 1964, Chile 1973, Argentina 1976"}, {"id": "d818e021-9c44-46d1-936a-6c3181f59966", "type": "concept", "title": "Operation Condor"}, {"id": "37009554-71d4-4cf2-ad03-9a5216a7a228", "type": "concept", "title": "Central American civil wars"}, {"id": "28d34ad0-a254-4155-9efa-1ee18a0345bd", "type": "concept", "title": "Disappearances, torture, and exile"}], "description": "Cold War violence must be studied through both state structures and lived experiences of fear, resistance, exile, and survival."}, {"id": "4e33c20a-d10d-47b6-b70d-4332676f5177", "type": "subtopic", "title": "Human rights and memory", "children": [{"id": "e24f3a0b-6693-406a-868e-ca8c9f769e5c", "type": "concept", "title": "Mothers and Grandmothers of Plaza de Mayo"}, {"id": "79d455d4-365c-44a1-9239-64e103b4298b", "type": "concept", "title": "Truth commissions"}, {"id": "4bd69548-36ee-40c2-bb0d-5dcbd1a2bc1c", "type": "concept", "title": "Testimonio and survivor memory"}, {"id": "f390c6e5-2e03-4e2c-b0a2-a140c9aed5fb", "type": "concept", "title": "Trials, amnesties, and archives"}], "description": "Human-rights movements transformed politics by documenting violence, demanding truth, and redefining justice."}]}, {"id": "04fd2c8b-391c-4c4c-9ee1-5112a69a9f7c", "type": "topic", "title": "Democracy, Neoliberalism, Inequality, and New Social Movements", "description": "Assess post-1980s democratization, market reforms, debt, inequality, feminist, indigenous, Afro-Latin American, environmental, and LGBTQ movements.", "children": [{"id": "38be5792-385c-4cb2-9ca1-7cb321ddea7d", "type": "subtopic", "title": "Democratic transitions", "children": [{"id": "00e0b360-73c3-4d62-8334-d43954ad4238", "type": "concept", "title": "Elections and constitutional reform"}, {"id": "442ca8a2-8bcf-4eb1-97dc-da3ca2ac5bd8", "type": "concept", "title": "Civil-military relations"}, {"id": "b61d52f0-244a-45ba-9ad5-cd5bb67fbc9b", "type": "concept", "title": "Truth and reconciliation debates"}, {"id": "efb0b31b-7356-43f9-a437-21a275aa6a24", "type": "concept", "title": "Corruption, parties, and legitimacy"}], "description": "Students examine why military regimes ended and how new democracies dealt with debt, memory, institutions, and inequality."}, {"id": "1c82018f-6d39-4a55-b403-68a6affed7c3", "type": "subtopic", "title": "Neoliberalism and inequality", "children": [{"id": "43c9232f-f244-45fe-a834-59b787b51d0d", "type": "concept", "title": "Debt crisis and structural adjustment"}, {"id": "dc9a042b-ce94-48a9-bacf-d6e67f6c5662", "type": "concept", "title": "Privatization and austerity"}, {"id": "73cc9db1-437e-49d1-a8df-0e2327907e89", "type": "concept", "title": "Free trade and NAFTA"}, {"id": "9ece565d-940f-4ad9-bad8-7fb66f6509ba", "type": "concept", "title": "Informal work and precarity"}], "description": "Market reforms reshaped labor, welfare, public services, land, debt, and social protest."}, {"id": "8f4c53e9-ed3c-45eb-a014-15046c6b1227", "type": "subtopic", "title": "Indigenous, Afro-Latin American, feminist, environmental, and LGBTQ movements", "children": [{"id": "5f4690fc-e27d-48a1-afc1-10d009c5e52d", "type": "concept", "title": "Zapatistas and indigenous autonomy"}, {"id": "e353a8a9-23ed-427c-920f-85e18bcec6b9", "type": "concept", "title": "Afro-Latin American rights and anti-racism"}, {"id": "dcdbfb10-cb37-4b3f-aa8d-13ba7c00ce95", "type": "concept", "title": "Feminist movements and reproductive justice"}, {"id": "18771b36-4829-483b-83fe-b9ec42af3985", "type": "concept", "title": "Environmental justice and extractivism"}], "description": "New social movements broaden the story of democracy beyond elections into rights, territory, recognition, and survival."}]}, {"id": "ce6743fc-a798-48b0-a25a-908d379ea751", "type": "topic", "title": "Memory, Archives, Diaspora, Environment, and Contemporary Capstone", "description": "Synthesize the course through memory politics, archival practice, diaspora, environmental conflict, and a research or public-history project.", "children": [{"id": "2d9ce912-d8a3-4e99-9f7b-2e1e93e02f01", "type": "subtopic", "title": "Memory and public history", "children": [{"id": "407c7eb0-0992-4406-accb-a8b6b0807032", "type": "concept", "title": "Monuments, museums, and memorials"}, {"id": "2a2403fc-a00c-4128-aec2-a8056f6bfee9", "type": "concept", "title": "School textbooks and national holidays"}, {"id": "50ed0889-8750-4f9f-8f8d-eba1cb4e1737", "type": "concept", "title": "Truth commissions and testimonial archives"}, {"id": "e9707c83-be88-42c0-b1ed-3c41bdf6f2e2", "type": "concept", "title": "Contested heroes and silences"}], "description": "Students analyze how societies remember conquest, slavery, revolution, dictatorship, migration, and violence in public life."}, {"id": "640cbf0a-9d53-4be2-9a38-6b49f97ce8e1", "type": "subtopic", "title": "Environment and contemporary crisis", "children": [{"id": "ebc0148b-a00e-48c4-bbac-62c87557ae16", "type": "concept", "title": "Amazon deforestation"}, {"id": "6618d4bb-7fd3-4810-8e65-3755d1b30461", "type": "concept", "title": "Mining and water conflict"}, {"id": "77f352b4-1729-4c30-9d01-e1a41d6946d8", "type": "concept", "title": "Climate migration"}, {"id": "f2d4005d-33bd-43c6-8b85-45d1be843054", "type": "concept", "title": "Food systems and agro-industry"}], "description": "Environmental history links colonial extraction to current debates over mining, forests, water, climate, agriculture, and indigenous rights."}, {"id": "93f328d6-ef1a-4c3a-9fa9-8288aa20ab77", "type": "subtopic", "title": "Research capstone and ethical archives", "children": [{"id": "afe34bcb-e6f5-4878-b931-a6317c0ea4ad", "type": "concept", "title": "Research question and annotated bibliography"}, {"id": "49241dad-2876-4e41-a6e9-ab869c7f7bc8", "type": "concept", "title": "Primary-source portfolio"}, {"id": "d7ed1aee-df4a-427b-89a9-7b0f4da7b242", "type": "concept", "title": "Digital exhibit, podcast, map, or paper"}, {"id": "94744f0d-219c-459f-974e-9243a95e75dc", "type": "concept", "title": "Citation, language, and community ethics"}], "description": "The final project turns course themes into a source-based historical argument or public-facing research product."}]}], "dbBacked": true}$lathjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'latin-american-history'
);

update public.learning_paths
set
  title = 'Latin American History',
  goal = 'Latin American History',
  summary = 'A survey of Latin American history from pre-Columbian societies to the contemporary era. Students analyze conquest, colonialism, slavery, race, gender, labor, religion, and state formation with primary and secondary sources, compare national and regional experiences, and connect Latin America to Atlantic, Pacific, U.S., indigenous, African diaspora, and global histories.',
  data = $lathjson${"slug": "latin-american-history", "title": "Latin American History", "description": "A survey of Latin American history from pre-Columbian societies to the contemporary era. Students analyze conquest, colonialism, slavery, race, gender, labor, religion, and state formation with primary and secondary sources, compare national and regional experiences, and connect Latin America to Atlantic, Pacific, U.S., indigenous, African diaspora, and global histories.", "topics": [{"id": "7dd8f8af-53a7-4315-97d0-83c961f2d71d", "type": "topic", "title": "Historical Method, Geography, and the Idea of Latin America", "description": "Frame Latin America as a historically constructed region shaped by indigenous worlds, Iberian empires, Africa, migration, capitalism, and U.S./global power.", "children": [{"id": "2b6adfab-641e-47b9-aab9-9d034fff61d6", "type": "subtopic", "title": "Region, language, and naming", "children": [{"id": "15b55610-239a-4ee5-8f4e-6fba26cbcbb2", "type": "concept", "title": "Latin America, Ibero-America, the Caribbean, and Abya Yala"}, {"id": "017003f7-b934-4dc9-95f4-6fc46e7e47e7", "type": "concept", "title": "Spanish-, Portuguese-, French-, English-, and indigenous-language worlds"}, {"id": "0bc9749b-af12-4e26-aa96-43848fdd5e8d", "type": "concept", "title": "Mesoamerica, Andes, Amazonia, Southern Cone, Caribbean, and borderlands"}, {"id": "168bdaa2-1f12-4baa-bbb2-35d86ae88f9d", "type": "concept", "title": "Region as historical argument rather than fixed geography"}], "description": "Students begin by asking what Latin America means, who uses the term, and what histories the label includes or hides."}, {"id": "eeb5c9b8-d459-4bcb-b553-d37ef5c9dad8", "type": "subtopic", "title": "Sources and historical interpretation", "children": [{"id": "7c359657-ae5e-464f-b0d0-0d4e5dd9fb37", "type": "concept", "title": "Primary and secondary sources"}, {"id": "115cab09-1975-43b6-aa62-ea37ecc1fb3e", "type": "concept", "title": "Translation and colonial mediation"}, {"id": "0ec433d7-a8f9-4a3b-8ea0-e477f2b5ac67", "type": "concept", "title": "Archives, silence, and power"}, {"id": "c7c927be-ce13-476f-9563-99505b4df1a2", "type": "concept", "title": "Chronology, causation, and comparison"}], "description": "This subtopic builds the habits needed to read chronicles, court records, maps, oral histories, photographs, testimony, and scholarship critically."}, {"id": "f3f6511c-5dd9-4564-ba10-8a2a0ae2cc87", "type": "subtopic", "title": "Scale and connected histories", "children": [{"id": "7debeec4-d5ab-4c87-8fe7-7fc9e747bb5f", "type": "concept", "title": "Village, city, region, nation, empire, and world-system scales"}, {"id": "cdbc04ca-72f5-4bde-8048-1e2bfe46c964", "type": "concept", "title": "Atlantic and Pacific worlds"}, {"id": "730f5920-fcce-4394-9bd5-1b204d28c862", "type": "concept", "title": "U.S.-Latin American relations"}, {"id": "7ac69a50-58a9-4fbc-b508-03844de94b42", "type": "concept", "title": "Migration, diaspora, and transnational history"}], "description": "Latin American history becomes more intelligible when local communities, imperial systems, Atlantic/Pacific circuits, and global capitalism are studied together."}]}, {"id": "79c07580-4429-4336-961b-4ffb79222690", "type": "topic", "title": "Indigenous Americas before 1492", "description": "Study the diversity, scale, political sophistication, ecological knowledge, and cultural achievements of pre-Columbian societies.", "children": [{"id": "2f0fd1f0-495c-4832-8211-46789d474125", "type": "subtopic", "title": "Mesoamerican worlds", "children": [{"id": "4950a0e0-dd60-42e9-88e9-cf0b812b978f", "type": "concept", "title": "Olmec, Maya, Mexica/Aztec, and other societies"}, {"id": "dd2a8775-f592-43f4-a6f6-94425419a5d4", "type": "concept", "title": "Cities, tribute, calendars, and writing"}, {"id": "08af53b2-dd7b-4fa8-9c2f-c9092ee8d958", "type": "concept", "title": "Maize agriculture and chinampas"}, {"id": "7f087d77-380e-4648-8e75-d021c6d62ec0", "type": "concept", "title": "Religion, warfare, and political legitimacy"}], "description": "Students examine indigenous statecraft, urbanism, religion, agriculture, and writing before European arrival."}, {"id": "af3bbb3a-37bb-4c86-8939-59c530cb6c62", "type": "subtopic", "title": "Andean worlds", "children": [{"id": "55fcef0e-42df-4110-afa8-7c6780b04b10", "type": "concept", "title": "Chavin, Moche, Tiwanaku, Wari, and Inca"}, {"id": "dd868706-d318-407a-b105-bda699a1337c", "type": "concept", "title": "Ayllu, mit'a, and vertical archipelagos"}, {"id": "8521d195-0184-4f6d-b2d8-3870e7f5ec7f", "type": "concept", "title": "Quipu, roads, and imperial administration"}, {"id": "3463f65a-061c-46ed-ae58-26616f70f942", "type": "concept", "title": "Highland/coastal ecological systems"}], "description": "The Andes show another major path to complex society, empire, ecological management, and record keeping."}, {"id": "4411c513-df37-4393-ae2d-d53987dde7a3", "type": "subtopic", "title": "Caribbean, Amazonian, and diverse indigenous societies", "children": [{"id": "4c0f4530-f5f7-4ebe-8418-7077cdb3b0ea", "type": "concept", "title": "Taino and Carib societies"}, {"id": "57099eaf-f273-46dc-a9ec-b80a723022f3", "type": "concept", "title": "Amazonian settlement and earthworks"}, {"id": "4d3a813f-e2b4-40c7-a015-2e398c00c166", "type": "concept", "title": "Nomadic, semi-sedentary, and agricultural communities"}, {"id": "86f1de5d-da1e-4114-bdbb-0ac2e75070b4", "type": "concept", "title": "Indigenous diplomacy, trade, and environmental knowledge"}], "description": "The course avoids reducing pre-Columbian history to only empires by studying varied political and ecological forms."}]}, {"id": "46f76170-3717-4315-bcc1-11638d46eedf", "type": "topic", "title": "Conquest, Encounter, Disease, and Colonial Violence", "description": "Analyze conquest as a contested process involving indigenous allies, military force, epidemic disease, translation, law, and memory.", "children": [{"id": "5a0481f2-a415-4d53-bdbc-b72ab109d1e4", "type": "subtopic", "title": "Conquest as contested process", "children": [{"id": "6e352e0b-8f98-44b8-b344-7e56b2115535", "type": "concept", "title": "Cortes, Malintzin, and indigenous allies"}, {"id": "19773756-07b7-407d-bdc7-8ae31bd0b9cd", "type": "concept", "title": "Pizarro and Andean civil war"}, {"id": "029ad4a7-4a18-45a4-8505-9472cd92b954", "type": "concept", "title": "Spanish, Portuguese, and Caribbean encounters"}, {"id": "03f5bfae-67aa-4a00-a233-1588d9a7cf1c", "type": "concept", "title": "Military technology, horses, and local politics"}], "description": "Conquest was not inevitable; it depended on alliances, rivalries, intelligence, technology, disease, and indigenous strategy."}, {"id": "556c6359-fe00-4c17-8435-e3ef40e31db0", "type": "subtopic", "title": "Disease and demographic catastrophe", "children": [{"id": "cb84c5db-44e5-4467-a3e1-d26fad7c7a51", "type": "concept", "title": "Smallpox, measles, influenza, and mortality"}, {"id": "cc84606a-7f06-4ae3-b537-f4b15374d521", "type": "concept", "title": "Demographic debate and evidence"}, {"id": "b4644772-2e47-47fe-ab27-81d91ed1062b", "type": "concept", "title": "Community disruption and resettlement"}, {"id": "f51029cd-0cff-415c-8a53-2da100cdbb62", "type": "concept", "title": "Disease, ecology, and colonial rule"}], "description": "Students learn how epidemics transformed power, labor, land, spirituality, and community survival."}, {"id": "a25aeeec-4f29-4cea-9bf4-83258c4394f3", "type": "subtopic", "title": "Memory, law, and conquest narratives", "children": [{"id": "86f6dcd7-5d93-4974-b830-b0b12186a426", "type": "concept", "title": "Chronicles and relaciones"}, {"id": "ac9c54f6-ed9a-45a9-8618-693d4d61a16c", "type": "concept", "title": "Las Casas and debates over conquest"}, {"id": "f51076b7-8997-4f9f-aee5-d8493b5ac6b2", "type": "concept", "title": "Indigenous pictorial and alphabetic accounts"}, {"id": "87f4b006-8e58-4896-af5a-be25371d4e06", "type": "concept", "title": "Conquest memory in modern nationalism"}], "description": "Accounts of conquest were arguments about legitimacy, rights, violence, and moral responsibility."}]}, {"id": "60639bdb-b65e-491a-a541-2b0382771558", "type": "topic", "title": "Iberian Colonial Rule: Crown, Church, Cities, and Law", "description": "Understand how Spanish and Portuguese empires governed territory, souls, labor, land, and local communities.", "children": [{"id": "d109e233-6693-43d0-9df1-072b787dbb28", "type": "subtopic", "title": "Colonial institutions", "children": [{"id": "4c79af57-2c72-4612-842f-dcefe7a20a2d", "type": "concept", "title": "Viceroyalties, audiencias, cabildos, and governors"}, {"id": "dee3914e-07bd-47d2-8ea5-2087d24c00d7", "type": "concept", "title": "Portuguese captaincies and Brazil's colonial administration"}, {"id": "7a028ecd-28ff-4252-af0f-454ada1c7e9f", "type": "concept", "title": "Bureaucracy, patronage, and corruption"}, {"id": "e9d0ac24-d86d-4c1f-bc39-ff47870987be", "type": "concept", "title": "Cities as colonial power centers"}], "description": "Students identify the administrative machinery of empire and how distant monarchies governed local worlds."}, {"id": "57d08b4b-a57b-4abf-8e5b-63527488f235", "type": "subtopic", "title": "Church, conversion, and religious life", "children": [{"id": "b0b93bc2-3f9a-4edc-99d6-78183930fa35", "type": "concept", "title": "Missionary orders and evangelization"}, {"id": "c9210a2b-13ce-4d64-9c8d-ea0472aa7193", "type": "concept", "title": "Syncretism and indigenous Christianity"}, {"id": "42837c7d-7b37-4cbf-942f-0f1e7680ac90", "type": "concept", "title": "Inquisition and moral regulation"}, {"id": "28ae834a-a05e-4d16-b4af-543afa17e4aa", "type": "concept", "title": "Confraternities, festivals, and popular religion"}], "description": "Religion was central to colonization, education, social discipline, cultural exchange, and resistance."}, {"id": "504e1867-98b8-43f9-93bb-3d8c88efaad5", "type": "subtopic", "title": "Law and indigenous communities", "children": [{"id": "fd227b0b-5186-4725-b2ca-54f108691d74", "type": "concept", "title": "Republic of Indians and Republic of Spaniards"}, {"id": "0b1d4e08-da4b-4791-b4ff-619c9f7faa5e", "type": "concept", "title": "Tribute and resguardos"}, {"id": "63ed1268-95b9-48fa-bf90-bb3eaefdcd53", "type": "concept", "title": "Land titles and legal petitions"}, {"id": "239de905-60e7-493e-9d90-05aae32aa41d", "type": "concept", "title": "Customary authority and native cabildos"}], "description": "Colonial rule depended on legal categories that both constrained and enabled indigenous survival."}]}, {"id": "822d47b4-6853-4d50-8543-b2e648bec665", "type": "topic", "title": "Race, Caste, Gender, Family, and Everyday Colonial Society", "description": "Examine how colonial hierarchy was made through race, gender, sexuality, honor, household life, religion, and legal categories.", "children": [{"id": "7303340a-b162-4f33-aa25-e1f4cb264967", "type": "subtopic", "title": "Caste and racial formation", "children": [{"id": "f8c45cc6-c2d4-46ad-960e-75a4be79af11", "type": "concept", "title": "Spaniards, Portuguese, indigenous peoples, Africans, mestizos, mulattos, and castas"}, {"id": "c88ce3c9-0083-4e55-b27b-c359c4e331db", "type": "concept", "title": "Limpieza de sangre and honor"}, {"id": "5885dd89-ccc7-4cbb-8b50-dbd3efd2f51a", "type": "concept", "title": "Casta paintings and visual classification"}, {"id": "0b01c179-5faf-4708-8063-37b393fe5125", "type": "concept", "title": "Mobility, ambiguity, and passing"}], "description": "Race in colonial Latin America was made through law, labor, ancestry, reputation, appearance, and local negotiation."}, {"id": "44deef19-55c0-4663-86ff-c053763deef8", "type": "subtopic", "title": "Gender, sexuality, and household power", "children": [{"id": "bc14267a-3d9b-4967-a035-c319b366f53a", "type": "concept", "title": "Patriarchy and legal dependence"}, {"id": "42cdee81-22d3-41ab-9aa7-736244f8f679", "type": "concept", "title": "Marriage, dowry, and legitimacy"}, {"id": "72b88dec-88c5-40d9-9b29-eab17feb968b", "type": "concept", "title": "Sexual regulation and honor"}, {"id": "9ad9237e-65fb-4ee3-bea3-03d011d3591d", "type": "concept", "title": "Women in markets, households, convents, and courts"}], "description": "Colonial power operated through marriage, inheritance, reproduction, sexuality, domestic labor, and family status."}, {"id": "8af68f34-8662-4263-8e69-e961af2745d1", "type": "subtopic", "title": "Everyday life and popular culture", "children": [{"id": "c9ca8ad4-4770-47dd-9414-03e1fddc2c45", "type": "concept", "title": "Urban neighborhoods and rural villages"}, {"id": "482260b4-4896-4103-8836-3be3b2df038c", "type": "concept", "title": "Foodways, dress, music, and devotion"}, {"id": "3693ba79-4ca8-4896-8904-19777d3d911d", "type": "concept", "title": "Crime, courts, and social conflict"}, {"id": "7501fe9b-0b79-412d-882f-0054a75db489", "type": "concept", "title": "Popular healing, magic, and belief"}], "description": "Students examine how ordinary people shaped colonial society through work, faith, festivals, markets, conflict, and community life."}]}, {"id": "4bcf70d9-1bdc-460b-9a41-834f61cf466c", "type": "topic", "title": "Labor, Slavery, Mining, Plantations, and Atlantic/Pacific Economies", "description": "Connect Latin America to global capitalism through coerced labor, silver, sugar, slavery, trade, and environmental transformation.", "children": [{"id": "836331d8-3ba0-46a9-a810-afa4f30d76c0", "type": "subtopic", "title": "Coerced labor regimes", "children": [{"id": "5ec4224d-a9e9-433e-b930-c2b1ed805a21", "type": "concept", "title": "Encomienda, repartimiento, and mit'a"}, {"id": "0e0764d6-09eb-45fd-8b91-2fdccd25513b", "type": "concept", "title": "African slavery"}, {"id": "0d6af7a4-0588-4372-afc2-d51762c540b5", "type": "concept", "title": "Debt peonage and wage labor"}, {"id": "268d0a87-46d3-4c83-a6e2-5b37e3793926", "type": "concept", "title": "Domestic, artisan, and informal labor"}], "description": "Colonial economies were built on overlapping systems of forced, semi-free, and wage labor."}, {"id": "948ed347-ee21-4253-98c3-060734f4347a", "type": "subtopic", "title": "Silver, sugar, and global trade", "children": [{"id": "090bb54a-dd80-4869-9760-c79f21d55df8", "type": "concept", "title": "Potosi, Zacatecas, and mercury"}, {"id": "a04bc2dd-7475-4d67-b249-4a304c4bffc9", "type": "concept", "title": "Sugar plantations in Brazil and the Caribbean"}, {"id": "6d72ddc7-16a7-49a1-b848-74499b966d87", "type": "concept", "title": "Manila galleons and Pacific trade"}, {"id": "d9b1097b-b3e2-4eac-bce5-6f6693f9112f", "type": "concept", "title": "Contraband, piracy, and port cities"}], "description": "Latin America powered early modern global exchange through mines, plantations, ports, and transoceanic routes."}, {"id": "bac69496-8155-4672-9e36-5988647a3d4b", "type": "subtopic", "title": "Environment and extraction", "children": [{"id": "22ffa319-2a77-41f8-9f1d-27bab4e82516", "type": "concept", "title": "Deforestation and mining pollution"}, {"id": "012efa27-7243-4ee3-a4ca-42a44527cbc9", "type": "concept", "title": "Plantation monocultures"}, {"id": "b21bf206-9c8c-4b47-a03c-45ff4741cf30", "type": "concept", "title": "Livestock and land use change"}, {"id": "1cb208c3-03a4-46ef-af82-742a218f1947", "type": "concept", "title": "Indigenous ecological knowledge and survival"}], "description": "Extraction changed landscapes, bodies, animals, crops, and disease environments."}]}, {"id": "44de7e0e-cf94-4d32-b452-2b5f23b64c4a", "type": "topic", "title": "Reform, Enlightenment, Rebellion, and Late Colonial Crisis", "description": "Trace Bourbon and Pombaline reforms, new political ideas, popular revolts, and the weakening of colonial legitimacy.", "children": [{"id": "918ee89f-57f6-43c0-9dcf-094c521b11e3", "type": "subtopic", "title": "Bourbon and Pombaline reforms", "children": [{"id": "71e4150b-e25a-4c37-b514-fc6d7459fe76", "type": "concept", "title": "Taxation and administrative centralization"}, {"id": "6997ada1-b83c-4673-b945-c4c5dc65620f", "type": "concept", "title": "Militias and imperial defense"}, {"id": "f2594547-e4e8-444e-b218-c4c0d3517d01", "type": "concept", "title": "Expulsion of the Jesuits"}, {"id": "dd644593-b7ed-436e-8f5b-17d0235c8376", "type": "concept", "title": "Free trade reforms and monopoly changes"}], "description": "Late colonial reforms attempted to make empire more profitable, centralized, and militarized, but also intensified social conflict."}, {"id": "30a1ecb0-898e-47f7-9646-ec67b33edb2e", "type": "subtopic", "title": "Enlightenment and Atlantic politics", "children": [{"id": "0f9e6986-6582-4478-a375-27e8bb0a1e35", "type": "concept", "title": "Creole patriotism"}, {"id": "b37f497c-5d58-4faa-84d5-c87edea1d56d", "type": "concept", "title": "Scientific expeditions"}, {"id": "cb34aadb-c772-4e0c-b67c-d5a4a340dbd8", "type": "concept", "title": "Print culture and censorship"}, {"id": "8055c826-50bb-42c5-bb49-c368ce8df62e", "type": "concept", "title": "Natural rights and political economy"}], "description": "New ideas about rights, sovereignty, science, economy, and reform circulated unevenly through colonial societies."}, {"id": "bbe81c4b-6046-4d84-8d31-1ddd0c8ca2cf", "type": "subtopic", "title": "Popular rebellion and crisis", "children": [{"id": "da303ff9-fd65-4567-8ac4-b6d897f01cad", "type": "concept", "title": "Tupac Amaru II and Andean rebellion"}, {"id": "34a46f1f-863f-4320-84c5-cea4d828d444", "type": "concept", "title": "Comunero revolts"}, {"id": "29433f73-936c-4a7a-bb3c-23e5765ae2d3", "type": "concept", "title": "Slave resistance and marronage"}, {"id": "e9512612-7d2b-4a97-bf41-6f258e92d174", "type": "concept", "title": "Haitian Revolution's regional impact"}], "description": "Rebellions reveal the limits of colonial authority and the diversity of indigenous, enslaved, creole, and popular politics."}]}, {"id": "915187e1-830c-44c6-8165-43bb764d0f64", "type": "topic", "title": "Independence Revolutions and Postcolonial State Formation", "description": "Compare independence movements and the difficult creation of republics, monarchies, constitutions, citizenship, and national territories.", "children": [{"id": "dce48a2e-fe4d-4660-883f-4dfc5a407ea2", "type": "subtopic", "title": "Causes and paths to independence", "children": [{"id": "890c84a3-56d8-41c9-bf6c-4b52e5b56340", "type": "concept", "title": "Napoleonic invasion of Iberia"}, {"id": "7cffe082-310c-44f1-96d8-19e7593c1255", "type": "concept", "title": "Juntas and sovereignty debates"}, {"id": "8c6a8b3a-4c1b-4053-80b8-11106d41051a", "type": "concept", "title": "Mexico, Gran Colombia, Rio de la Plata, Chile, Peru, and Brazil"}, {"id": "cd0b7932-9207-4a38-a470-30428a1be35a", "type": "concept", "title": "Haiti and the Caribbean"}], "description": "Independence emerged from imperial crisis, local grievances, Atlantic revolutions, social conflict, and military mobilization."}, {"id": "10eb7358-fe83-4134-9573-988aef0af1ea", "type": "subtopic", "title": "Leaders, armies, and popular participation", "children": [{"id": "725c51a1-fa06-413b-be09-d04cf9a54440", "type": "concept", "title": "Bolivar, San Martin, Hidalgo, Morelos, O'Higgins, and Pedro I"}, {"id": "af4bf636-b871-43f5-8c5b-c5fbb4cd2656", "type": "concept", "title": "Royalists and patriots"}, {"id": "2fae862a-df76-40e0-9f09-83ce5850cf24", "type": "concept", "title": "Guerrilla war and local mobilization"}, {"id": "cef9837f-b8d5-4fab-b71d-43263ab339d2", "type": "concept", "title": "Race, slavery, and promises of citizenship"}], "description": "Students compare elite projects with the actions of indigenous communities, enslaved people, free people of color, soldiers, and local militias."}, {"id": "2c2d3f2f-eb55-4e34-9e9d-1745ba913266", "type": "subtopic", "title": "Postcolonial state-building", "children": [{"id": "fe867249-6971-403b-a866-60331fb269d0", "type": "concept", "title": "Constitutions and republicanism"}, {"id": "f5f70343-f6cb-4b59-921b-8d3c867702eb", "type": "concept", "title": "Federalism versus centralism"}, {"id": "4581c74e-85a9-4c4c-85e5-f6fad0152623", "type": "concept", "title": "Military politics and caudillos"}, {"id": "8af91856-7d6f-4db8-b7bc-a0b5273c71ef", "type": "concept", "title": "Borders, debt, and diplomatic recognition"}], "description": "Independence did not automatically produce stable nations; it opened conflicts over authority, territory, citizenship, debt, and law."}]}, {"id": "0aa51b8d-2594-4330-ac47-71a0a140c5e4", "type": "topic", "title": "Nineteenth-Century Nation-Building, Liberalism, Caudillismo, and Citizenship", "description": "Study the conflicts over federalism, centralism, church power, race, land, indigenous rights, and political authority after independence.", "children": [{"id": "6afaeb6c-7ed5-458b-b779-d08a7ea66e6a", "type": "subtopic", "title": "Liberalism and conservative reaction", "children": [{"id": "0d37aa03-3612-4af7-af17-5a819419a1a7", "type": "concept", "title": "Church-state conflict"}, {"id": "b329d110-a7fc-4f22-84b4-54b114088593", "type": "concept", "title": "Civil codes and legal reform"}, {"id": "86b8739c-8069-4af5-bc9c-65737d1fe623", "type": "concept", "title": "Education and secularization"}, {"id": "4ea60e4c-6088-4ae6-af18-813b7df56ee6", "type": "concept", "title": "Conservative order and liberal reform"}], "description": "This subtopic explains the major political languages that shaped conflict over church, state, property, education, and citizenship."}, {"id": "49fa1a17-480c-4d44-9f71-3320c698cfa6", "type": "subtopic", "title": "Caudillismo, federalism, and regional power", "children": [{"id": "830bc2b9-8387-48a1-b840-dd33bdbefc48", "type": "concept", "title": "Caudillos and patron-client politics"}, {"id": "e02d7035-78e1-48b2-99d2-87cce3980b3f", "type": "concept", "title": "Federalist and centralist conflicts"}, {"id": "3fd2e7c7-1970-43c0-abcf-c4ef523396d0", "type": "concept", "title": "Civil wars and regionalism"}, {"id": "b7c15e42-c8c4-4e84-a2d0-ebe94848da60", "type": "concept", "title": "Military recruitment and taxation"}], "description": "Political instability becomes more understandable when students see how local power, war, patronage, and weak institutions interacted."}, {"id": "da65c94a-e02d-4731-bc93-546a3774af30", "type": "subtopic", "title": "Citizenship, race, and indigenous communities", "children": [{"id": "f75cfb3d-5c65-464d-8096-be3c1de87813", "type": "concept", "title": "Abolition and free womb laws"}, {"id": "84cf2b51-588c-4d21-b271-94ba9e529b03", "type": "concept", "title": "Indigenous land privatization"}, {"id": "10eabbcf-8e1c-49de-bd20-e429207b5344", "type": "concept", "title": "Literacy, property, and voting restrictions"}, {"id": "06399eba-af8b-4b69-b521-7aabb36c8e73", "type": "concept", "title": "National myths of mestizaje and whitening"}], "description": "Nation-building often promised equality while dispossessing or excluding indigenous, Afro-descendant, rural, and poor populations."}]}, {"id": "9c6e67ab-fa00-4a6f-88fc-bf5084ee76ed", "type": "topic", "title": "Export Economies, Land, Modernization, and Indigenous Dispossession", "description": "Analyze how railroads, coffee, sugar, nitrates, rubber, cattle, and land concentration remade societies and landscapes.", "children": [{"id": "e66e5972-02a3-496f-aabb-fa5cf398131a", "type": "subtopic", "title": "Export-led growth", "children": [{"id": "8f5ec451-e832-4c44-86ab-00b687e6553b", "type": "concept", "title": "Coffee, sugar, guano, nitrates, rubber, cattle, bananas, and copper"}, {"id": "c52246e7-d6f8-49b9-93c8-8b59cce27ced", "type": "concept", "title": "Railroads and ports"}, {"id": "2940db59-4808-4348-bb6f-cf4f7caf95e6", "type": "concept", "title": "British and U.S. investment"}, {"id": "423e6eed-9816-4dc4-bbbb-42680bf9f879", "type": "concept", "title": "Boom-and-bust cycles"}], "description": "Students study how global demand transformed national economies and deepened dependence on land, credit, railroads, and foreign capital."}, {"id": "84bbd330-7b31-465e-a683-65832cbab0e6", "type": "subtopic", "title": "Land, labor, and rural conflict", "children": [{"id": "43458ddd-acdc-40ec-a41f-3e35f685a369", "type": "concept", "title": "Haciendas and latifundia"}, {"id": "8cf22384-863f-4082-aac7-f32af9440475", "type": "concept", "title": "Debt peonage and labor drafts"}, {"id": "7831ede7-06a5-4a64-9f38-94d761657b54", "type": "concept", "title": "Liberal land laws"}, {"id": "7787abcc-a642-4fd9-ab7a-42acc14de898", "type": "concept", "title": "Rural rebellion and community defense"}], "description": "Modernization often concentrated land and coerced labor while provoking peasant and indigenous resistance."}, {"id": "ce614cdc-7d06-42d4-96b5-a16a71f560bc", "type": "subtopic", "title": "Modernity, cities, and inequality", "children": [{"id": "9549111e-b33b-42ad-8066-2abe972817f1", "type": "concept", "title": "Positivism and order/progress ideologies"}, {"id": "c4533441-b2b8-45f0-ac48-546e9b0fca96", "type": "concept", "title": "Urban planning and public health"}, {"id": "71c7ae49-87df-420e-b174-50cb3f7a255b", "type": "concept", "title": "Immigration and whitening projects"}, {"id": "e9d2a30a-5642-4d92-b2a8-e02572ed1df6", "type": "concept", "title": "Police, prisons, and social control"}], "description": "Urban elites promoted progress, science, and order while social inequality and racial exclusion persisted."}]}, {"id": "efda739c-9df0-415f-87a0-b7135e7da03b", "type": "topic", "title": "Revolution, Reform, and Social Movements", "description": "Examine major revolutionary and reform traditions, including Mexico, Cuba, labor organizing, peasant mobilization, student movements, and liberation theology.", "children": [{"id": "07d70725-1964-4c86-8b84-495ae1057f72", "type": "subtopic", "title": "Mexican Revolution", "children": [{"id": "ae5cdb22-5f90-4ce1-a9fa-5098e4f24e12", "type": "concept", "title": "Porfiriato and inequality"}, {"id": "feefde50-a0f7-4457-9cdf-c8e6e9e8865d", "type": "concept", "title": "Madero, Zapata, Villa, Carranza, and Cardenas"}, {"id": "e59fe5dc-2525-4478-9552-df7ea22a8c30", "type": "concept", "title": "Constitution of 1917"}, {"id": "a9a6116f-29ff-4d02-bbc5-8f12b76cba53", "type": "concept", "title": "Land reform, education, and cultural nationalism"}], "description": "The Mexican Revolution offers a major case for agrarian reform, popular mobilization, nationalism, constitutionalism, and state-building."}, {"id": "7ad88eba-4d0f-4a9f-b1b3-04c7a636886c", "type": "subtopic", "title": "Cuban Revolution and revolutionary imaginaries", "children": [{"id": "a8c8e976-fb6d-4d11-a63d-3ac8c3d544ab", "type": "concept", "title": "1959 revolution"}, {"id": "d1b21c07-2340-41e3-a7b7-18ffbb4a9742", "type": "concept", "title": "Fidel Castro, Che Guevara, and revolutionary state-building"}, {"id": "17dc6bde-3f7a-4df8-a912-891c2a24f77c", "type": "concept", "title": "Bay of Pigs and missile crisis"}, {"id": "65594009-dce7-43ee-b1c8-6df105346663", "type": "concept", "title": "Health, education, dissent, and exile"}], "description": "Cuba shaped regional debates about imperialism, socialism, nationalism, armed struggle, and social justice."}, {"id": "2b37355c-fd4c-47c4-9ca3-529dd51c8330", "type": "subtopic", "title": "Labor, students, peasants, and liberation theology", "children": [{"id": "0f6e7e5c-5d48-4cb0-b8ff-2ce235dbb9c2", "type": "concept", "title": "Unions and strikes"}, {"id": "3a69bf0c-4fd9-41d7-b6f0-775992b49801", "type": "concept", "title": "Student movements and 1968"}, {"id": "325fa2cd-f659-4ec2-9fa7-d29f35834661", "type": "concept", "title": "Peasant leagues and land occupations"}, {"id": "fd224713-c619-452c-8ea9-c3e7118f6ef5", "type": "concept", "title": "Base communities and liberation theology"}], "description": "Social movements show how ordinary people made history through organization, protest, cultural politics, and religious activism."}]}, {"id": "7aa16931-6089-47c1-9c32-1f4952515006", "type": "topic", "title": "Populism, Developmentalism, Urbanization, and Migration", "description": "Explore twentieth-century mass politics, import-substitution industrialization, labor rights, urban growth, migration, and cultural change.", "children": [{"id": "32cb6dc6-c753-4c8d-be50-3e5a2de8a918", "type": "subtopic", "title": "Populism and mass politics", "children": [{"id": "22a00de4-03ce-44ea-8c63-9b6851ed690b", "type": "concept", "title": "Peronism"}, {"id": "b9c35501-adae-4c46-bf6d-bdace3d4b07a", "type": "concept", "title": "Vargas and Estado Novo"}, {"id": "c65d99fd-32ef-4967-978f-36d2eccf7d5a", "type": "concept", "title": "Cardenismo"}, {"id": "49baebbe-978f-4a65-836e-750a57e824ba", "type": "concept", "title": "Mass parties, unions, and corporatism"}], "description": "Populism helps students understand charismatic leadership, labor incorporation, nationalism, welfare promises, and political polarization."}, {"id": "f7f48868-37cf-4281-a1f4-578f6fde2699", "type": "subtopic", "title": "Developmentalism and urban change", "children": [{"id": "fdb0b441-d728-4f61-bc56-eca01ae01122", "type": "concept", "title": "Import-substitution industrialization"}, {"id": "8f7f61bb-7e32-4530-9bf0-c5ecb3c93b9c", "type": "concept", "title": "State planning and public enterprises"}, {"id": "09dab1bb-6b1c-4361-bfbc-93dc296c90ef", "type": "concept", "title": "Informal settlements and urban services"}, {"id": "e5234aba-0c47-4999-8e8e-66205f580e1e", "type": "concept", "title": "Culture industries, radio, film, and television"}], "description": "Mid-twentieth-century states pursued industrialization and modernization while cities grew rapidly and unevenly."}, {"id": "75c4472a-684f-464e-8e2b-b1a6bd47e034", "type": "subtopic", "title": "Migration and transnational families", "children": [{"id": "1c52b328-c70c-4a70-9f46-bb5fccd5cfdd", "type": "concept", "title": "Rural-to-urban migration"}, {"id": "ee4ba444-1aeb-47ef-87b6-6305eb47fd2d", "type": "concept", "title": "Internal displacement"}, {"id": "4c38e446-9dec-42d6-bea9-fc62dbc3f711", "type": "concept", "title": "Guest work and border labor"}, {"id": "dc614e51-3150-42ec-be43-5bd303059bff", "type": "concept", "title": "Diaspora, remittances, and family separation"}], "description": "Migration links rural change, urbanization, labor markets, identity, remittances, and U.S.-Latin American relations."}]}, {"id": "6ef58fb0-c7eb-4416-9aad-0a0936685016", "type": "topic", "title": "Cold War Latin America: Intervention, Dictatorship, Revolution, and Human Rights", "description": "Study the Cold War through U.S. policy, revolutionary movements, military regimes, state terror, civil war, and human-rights struggles.", "children": [{"id": "2c898113-9071-4dc8-bc69-6b2ac2f94fb6", "type": "subtopic", "title": "U.S. policy and regional Cold War", "children": [{"id": "3b12c618-a32e-4611-80e3-97041566c325", "type": "concept", "title": "Guatemala 1954"}, {"id": "c6ca11a6-512b-4837-816a-186609184f2e", "type": "concept", "title": "Alliance for Progress"}, {"id": "0104dcf6-d5fb-405f-88b3-796539d8ee57", "type": "concept", "title": "School of the Americas"}, {"id": "8fc4dc75-b77c-4600-8268-861255c867ba", "type": "concept", "title": "CIA, coups, and counterinsurgency"}], "description": "Students connect Latin American politics to anticommunism, development aid, covert action, military training, and hemispheric security."}, {"id": "6a2a86a5-3d1d-4397-af76-5045cced9168", "type": "subtopic", "title": "Dictatorship, state terror, and civil war", "children": [{"id": "71ed76ca-4955-4195-9ff1-188b1c5032df", "type": "concept", "title": "Brazil 1964, Chile 1973, Argentina 1976"}, {"id": "d818e021-9c44-46d1-936a-6c3181f59966", "type": "concept", "title": "Operation Condor"}, {"id": "37009554-71d4-4cf2-ad03-9a5216a7a228", "type": "concept", "title": "Central American civil wars"}, {"id": "28d34ad0-a254-4155-9efa-1ee18a0345bd", "type": "concept", "title": "Disappearances, torture, and exile"}], "description": "Cold War violence must be studied through both state structures and lived experiences of fear, resistance, exile, and survival."}, {"id": "4e33c20a-d10d-47b6-b70d-4332676f5177", "type": "subtopic", "title": "Human rights and memory", "children": [{"id": "e24f3a0b-6693-406a-868e-ca8c9f769e5c", "type": "concept", "title": "Mothers and Grandmothers of Plaza de Mayo"}, {"id": "79d455d4-365c-44a1-9239-64e103b4298b", "type": "concept", "title": "Truth commissions"}, {"id": "4bd69548-36ee-40c2-bb0d-5dcbd1a2bc1c", "type": "concept", "title": "Testimonio and survivor memory"}, {"id": "f390c6e5-2e03-4e2c-b0a2-a140c9aed5fb", "type": "concept", "title": "Trials, amnesties, and archives"}], "description": "Human-rights movements transformed politics by documenting violence, demanding truth, and redefining justice."}]}, {"id": "04fd2c8b-391c-4c4c-9ee1-5112a69a9f7c", "type": "topic", "title": "Democracy, Neoliberalism, Inequality, and New Social Movements", "description": "Assess post-1980s democratization, market reforms, debt, inequality, feminist, indigenous, Afro-Latin American, environmental, and LGBTQ movements.", "children": [{"id": "38be5792-385c-4cb2-9ca1-7cb321ddea7d", "type": "subtopic", "title": "Democratic transitions", "children": [{"id": "00e0b360-73c3-4d62-8334-d43954ad4238", "type": "concept", "title": "Elections and constitutional reform"}, {"id": "442ca8a2-8bcf-4eb1-97dc-da3ca2ac5bd8", "type": "concept", "title": "Civil-military relations"}, {"id": "b61d52f0-244a-45ba-9ad5-cd5bb67fbc9b", "type": "concept", "title": "Truth and reconciliation debates"}, {"id": "efb0b31b-7356-43f9-a437-21a275aa6a24", "type": "concept", "title": "Corruption, parties, and legitimacy"}], "description": "Students examine why military regimes ended and how new democracies dealt with debt, memory, institutions, and inequality."}, {"id": "1c82018f-6d39-4a55-b403-68a6affed7c3", "type": "subtopic", "title": "Neoliberalism and inequality", "children": [{"id": "43c9232f-f244-45fe-a834-59b787b51d0d", "type": "concept", "title": "Debt crisis and structural adjustment"}, {"id": "dc9a042b-ce94-48a9-bacf-d6e67f6c5662", "type": "concept", "title": "Privatization and austerity"}, {"id": "73cc9db1-437e-49d1-a8df-0e2327907e89", "type": "concept", "title": "Free trade and NAFTA"}, {"id": "9ece565d-940f-4ad9-bad8-7fb66f6509ba", "type": "concept", "title": "Informal work and precarity"}], "description": "Market reforms reshaped labor, welfare, public services, land, debt, and social protest."}, {"id": "8f4c53e9-ed3c-45eb-a014-15046c6b1227", "type": "subtopic", "title": "Indigenous, Afro-Latin American, feminist, environmental, and LGBTQ movements", "children": [{"id": "5f4690fc-e27d-48a1-afc1-10d009c5e52d", "type": "concept", "title": "Zapatistas and indigenous autonomy"}, {"id": "e353a8a9-23ed-427c-920f-85e18bcec6b9", "type": "concept", "title": "Afro-Latin American rights and anti-racism"}, {"id": "dcdbfb10-cb37-4b3f-aa8d-13ba7c00ce95", "type": "concept", "title": "Feminist movements and reproductive justice"}, {"id": "18771b36-4829-483b-83fe-b9ec42af3985", "type": "concept", "title": "Environmental justice and extractivism"}], "description": "New social movements broaden the story of democracy beyond elections into rights, territory, recognition, and survival."}]}, {"id": "ce6743fc-a798-48b0-a25a-908d379ea751", "type": "topic", "title": "Memory, Archives, Diaspora, Environment, and Contemporary Capstone", "description": "Synthesize the course through memory politics, archival practice, diaspora, environmental conflict, and a research or public-history project.", "children": [{"id": "2d9ce912-d8a3-4e99-9f7b-2e1e93e02f01", "type": "subtopic", "title": "Memory and public history", "children": [{"id": "407c7eb0-0992-4406-accb-a8b6b0807032", "type": "concept", "title": "Monuments, museums, and memorials"}, {"id": "2a2403fc-a00c-4128-aec2-a8056f6bfee9", "type": "concept", "title": "School textbooks and national holidays"}, {"id": "50ed0889-8750-4f9f-8f8d-eba1cb4e1737", "type": "concept", "title": "Truth commissions and testimonial archives"}, {"id": "e9707c83-be88-42c0-b1ed-3c41bdf6f2e2", "type": "concept", "title": "Contested heroes and silences"}], "description": "Students analyze how societies remember conquest, slavery, revolution, dictatorship, migration, and violence in public life."}, {"id": "640cbf0a-9d53-4be2-9a38-6b49f97ce8e1", "type": "subtopic", "title": "Environment and contemporary crisis", "children": [{"id": "ebc0148b-a00e-48c4-bbac-62c87557ae16", "type": "concept", "title": "Amazon deforestation"}, {"id": "6618d4bb-7fd3-4810-8e65-3755d1b30461", "type": "concept", "title": "Mining and water conflict"}, {"id": "77f352b4-1729-4c30-9d01-e1a41d6946d8", "type": "concept", "title": "Climate migration"}, {"id": "f2d4005d-33bd-43c6-8b85-45d1be843054", "type": "concept", "title": "Food systems and agro-industry"}], "description": "Environmental history links colonial extraction to current debates over mining, forests, water, climate, agriculture, and indigenous rights."}, {"id": "93f328d6-ef1a-4c3a-9fa9-8288aa20ab77", "type": "subtopic", "title": "Research capstone and ethical archives", "children": [{"id": "afe34bcb-e6f5-4878-b931-a6317c0ea4ad", "type": "concept", "title": "Research question and annotated bibliography"}, {"id": "49241dad-2876-4e41-a6e9-ab869c7f7bc8", "type": "concept", "title": "Primary-source portfolio"}, {"id": "d7ed1aee-df4a-427b-89a9-7b0f4da7b242", "type": "concept", "title": "Digital exhibit, podcast, map, or paper"}, {"id": "94744f0d-219c-459f-974e-9243a95e75dc", "type": "concept", "title": "Citation, language, and community ethics"}], "description": "The final project turns course themes into a source-based historical argument or public-facing research product."}]}], "dbBacked": true}$lathjson$::jsonb,
